(2195277, 301250, 44882, '<td valign="top">The contrast and levels are fine, but there is too much blurr in the forground, IMHO.</td>', 'The contrast and levels are fine, but there is too much blurr in the forground, IMHO.', '2006-03-02 03:44:25.000000', NULL, 1),
