(2195286, 301389, 36472, '<td valign="top">I really like this shot! The balance of your usage of the light with the darkness is striking, coupled with the drops of water this makes for an amazing shot. Finally, the border draws the colors together as well as keeps your eyes within the shot and flowing along the curves of the light. Easily my favorite shot in the whole set. If you don''t win blue then there is seriously something wrong in the world.  :) Good luck.</td>', 'I really like this shot! The balance of your usage of the light with the darkness is striking, coupled with the drops of water this makes for an amazing shot. Finally, the border draws the colors together as well as keeps your eyes within the shot and flowing along the curves of the light. Easily my favorite shot in the whole set. If you don''t win blue then there is seriously something wrong in the world.  :) Good luck.', '2006-03-02 03:49:15.000000', NULL, 1),
(2195302, 301372, 52472, '<td valign="top">Great picture, ugly frame. 9</td>', 'Great picture, ugly frame. 9', '2006-03-02 04:39:50.000000', NULL, 1),
