(2200734, 300364, 46466, '<td valign="top">I once had a bird named Buffet. But it was pronounced buff-ay. I suppose that is because he cooked so well.</td>', 'I once had a bird named Buffet. But it was pronounced buff-ay. I suppose that is because he cooked so well.', '2006-03-04 22:42:44.000000', NULL, 1),
(2200754, 301378, 46466, '<td valign="top">Some may find your photo to be an interesting play on words. That is because they, like you, are cool.</td>', 'Some may find your photo to be an interesting play on words. That is because they, like you, are cool.', '2006-03-04 22:50:50.000000', NULL, 1),
