(2200997, 300057, 41574, '<td valign="top">I think you missed the point of the challenge: You were supposed to illuminate the scene with a non-stationary source of light, not use environmental light to illuminate your shot.</td>', 'I think you missed the point of the challenge: You were supposed to illuminate the scene with a non-stationary source of light, not use environmental light to illuminate your shot.', '2006-03-05 02:01:54.000000', NULL, 1),
(2200998, 301696, 41574, '<td valign="top">Too small too critically judge. Also, a very pixelated submission. Most important, however, you missed the point of the challenge: it was to use a non-stationary source of light to illuminate your subject. Unless you used the sun to illuminate the earth, your shot doesn''t work. Sorry, and better luck next time.</td>', 'Too small too critically judge. Also, a very pixelated submission. Most important, however, you missed the point of the challenge: it was to use a non-stationary source of light to illuminate your subject. Unless you used the sun to illuminate the earth, your shot doesn''t work. Sorry, and better luck next time.', '2006-03-05 02:03:29.000000', NULL, 1),
(2200999, 301629, 41574, '<td valign="top">I think this is the best entry I''ve seen so far. In any event, it''s my first "10." Excellent work.</td>', 'I think this is the best entry I''ve seen so far. In any event, it''s my first "10." Excellent work.', '2006-03-05 02:07:35.000000', NULL, 1),
(2201000, 301144, 41574, '<td valign="top">It''s a great shot, but you didn''t follow the guidelines of the challenge: Use a non-stationary source of light to illuminate your subject.</td>', 'It''s a great shot, but you didn''t follow the guidelines of the challenge: Use a non-stationary source of light to illuminate your subject.', '2006-03-05 02:09:08.000000', NULL, 1),
(2201001, 301031, 41574, '<td valign="top">Very creative. A bit dull, but I love what you''ve done, nevertheless.</td>', 'Very creative. A bit dull, but I love what you''ve done, nevertheless.', '2006-03-05 02:09:54.000000', NULL, 1),
(2201003, 301385, 41574, '<td valign="top">It''s a shame that the woman couldn''t be put in focus (maybe a light flash could have done the trick), but I love the shot, nonetheless.</td>', 'It''s a shame that the woman couldn''t be put in focus (maybe a light flash could have done the trick), but I love the shot, nonetheless.', '2006-03-05 02:10:45.000000', NULL, 1),
