(2206624, 301328, 47020, '<td valign="top">very cool.</td>', 'very cool.', '2006-03-07 05:46:42.000000', NULL, 1),
(2206625, 301693, 47020, '<td valign="top">hooray for fire poi.  :-)<br/> <br/>Is one of her chains shorter, or is that just an effect of a wide angle lens that one ring is inside the other?  fun.</td>', 'hooray for fire poi.  :-) Is one of her chains shorter, or is that just an effect of a wide angle lens that one ring is inside the other?  fun.', '2006-03-07 05:49:04.000000', NULL, 1),
(2206629, 301385, 47020, '<td valign="top">Nice concept and image.  Alas, the blurryness of her movement, while of course hard to eliminate, is distracting enough to knock a point or two off.  Still gets an 8 from me, though!</td>', 'Nice concept and image.  Alas, the blurryness of her movement, while of course hard to eliminate, is distracting enough to knock a point or two off.  Still gets an 8 from me, though!', '2006-03-07 05:52:37.000000', NULL, 1),
